static void epoch_free(Epoch *e){
#ifdef DOC_ENABLE_PLACED
if(e->placed)_Exit(1); /* explicit host-owned profile must be detached */
#endif
if(e->in_flight||e->reader_slots||pthread_mutex_destroy(&e->authority))_Exit(1);if(e->cell)for(size_t i=0;i<e->n;i++){clear(&e->cell[i].stable);clear(&e->cell[i].next);clear(&e->cell[i].candidate);}free(e->cell);free(e->dirty);free(e->have);free(e->saved_dirty);free(e->saved_have);free(e->need);free(e->blocked);free(e->queue);}
static int epoch_try_init(Epoch *e,const State *states,size_t n){*e=(Epoch){.states=states,.n=n};if(pthread_mutex_init(&e->authority,NULL))return 0;atomic_init(&e->cancelled,0);e->cell=zalloc(n,sizeof(Cell));e->dirty=zalloc(n,1);e->have=zalloc(n,1);e->saved_dirty=zalloc(n,1);e->saved_have=zalloc(n,1);e->need=zalloc(n,1);e->blocked=zalloc(n,1);e->queue=zalloc(n,sizeof(size_t));if(!e->cell||!e->dirty||!e->have||!e->saved_dirty||!e->saved_have||!e->need||!e->blocked||!e->queue){epoch_free(e);return 0;}for(size_t i=0;i<n;i++)e->dirty[i]=states[i].role==2;return 1;}
static void epoch_init(Epoch *e,const State *states,size_t n){if(!epoch_try_init(e,states,n))fail("epoch allocation");}
static int epoch_begin(Epoch *e){epoch_lock(e);if(!truth(F_life_begin(vb(e->in_flight),vi(e->attempt)))){epoch_unlock(e);return 0;}e->attempt++;e->in_flight=1;e->batch_state=0;atomic_store(&e->cancelled,0);memcpy(e->saved_dirty,e->dirty,e->n);memcpy(e->saved_have,e->have,e->n);for(size_t i=0;i<e->n;i++){Cell *c=e->cell+i;if(e->states[i].name)c->previous=*e->states[i].slot;c->replaced=c->supplied=c->failed=0;c->error=NULL;}e->evaluations=e->frontiers=e->parallel_frontiers=e->launched=0;epoch_unlock(e);return 1;}
static int epoch_finish(Epoch *e,int success){epoch_lock(e);if(!e->in_flight){epoch_unlock(e);return 0;}success=truth(F_life_commit(vb(e->in_flight),vb(e->batch_state==2),vb(success&&(!gpu_mode||gpu_healthy())),vb(epoch_cancelled(e))));for(size_t i=0;i<e->n;i++){Cell *c=e->cell+i;clear(&c->candidate);if(success){if(c->replaced){clear(&c->stable);c->stable=c->next;c->next=(Region){0};}}else{if(e->states[i].name)*e->states[i].slot=c->previous;clear(&c->next);}c->replaced=0;}if(!success){memcpy(e->dirty,e->saved_dirty,e->n);memcpy(e->have,e->saved_have,e->n);}else e->committed=e->attempt;
#ifdef DOC_ENABLE_PLACED
if(e->placed)placed_finish_epoch(e,success);
#endif
e->in_flight=0;epoch_unlock(e);return success;}
