/* Evaluation owns only its scratch/candidate regions. On failure, cleanup
 * precedes longjmp, so no pointer to an unwound stack region is retained. */
static int evaluate(Epoch *e,size_t i,const char *input){Cell *c=e->cell+i;const State *s=e->states+i;jmp_buf jump;failure_target=&jump;failure_message=NULL;if(setjmp(jump)){failure_target=NULL;c->failed=1;c->error=failure_message;clear(&c->candidate);return 0;}Region tmp;push(&tmp);V result=input?input_value(s->kind,input):s->eval();if(result.kind!=s->kind)fail("result kind");c->result=own(&c->candidate,result);pop(&tmp);failure_target=NULL;return 1;}
static void publish_private(Epoch *e,size_t i){Cell *c=e->cell+i;V *slot=e->states[i].slot;int changed=!e->have[i]||!equal(*slot,c->result);if(changed){clear(&c->next);c->next=c->candidate;c->candidate=(Region){0};*slot=c->result;c->replaced=1;doc_mark(i,e->dirty);}else clear(&c->candidate);e->have[i]=1;e->dirty[i]=0;}
