static size_t worker_count(size_t tasks){if(!truth(F_place_parallel(vi((int64_t)tasks))))return 1;cpu_set_t mask;size_t hw=1;if(sched_getaffinity(0,sizeof(mask),&mask)==0){int n=CPU_COUNT(&mask);if(n>0)hw=(size_t)n;}else if(errno==EINVAL){for(size_t bits=2u*CPU_SETSIZE;bits<=SIZE_MAX/2;bits*=2){cpu_set_t *large=CPU_ALLOC(bits);if(!large)break;size_t bytes=CPU_ALLOC_SIZE(bits);int rc=sched_getaffinity(0,bytes,large),error=errno;int n=rc==0?CPU_COUNT_S(bytes,large):0;CPU_FREE(large);if(!rc){if(n>0)hw=(size_t)n;break;}if(error!=EINVAL)break;}}const char *raw=getenv("DOC_WORKERS");if(raw&&*raw&&*raw!='-'){char *end;errno=0;unsigned long long v=strtoull(raw,&end,10);if(!errno&&!*end&&v&&v<hw)hw=(size_t)v;}return (size_t)num(F_place_workers(vi((int64_t)tasks),vi((int64_t)hw)));}
typedef struct {Epoch *e;const size_t *queue;size_t lo,hi;} Job;
static void *work(void *opaque){Job *j=opaque;for(size_t k=j->lo;k<j->hi&&!epoch_cancelled(j->e);k++){size_t i=j->queue[k];evaluate(j->e,i,NULL);}return NULL;}
static int execute_cpu(Epoch *e,const size_t *queue,size_t tasks){if(!tasks)return 1;size_t n=worker_count(tasks),started=0;Job *jobs=calloc(n,sizeof(Job));pthread_t *threads=calloc(n,sizeof(pthread_t));if(!jobs||!threads){free(jobs);free(threads);return 0;}for(size_t i=0;i<n;i++){jobs[i]=(Job){e,queue,tasks*i/n,tasks*(i+1)/n};}for(size_t i=1;i<n;i++){if(pthread_create(threads+i,NULL,work,jobs+i))break;started++;}work(jobs);for(size_t i=started+1;i<n;i++)work(jobs+i);for(size_t i=1;i<=started;i++){if(pthread_join(threads[i],NULL)){fprintf(stderr,"DOC: platform join failure; process stops without publication\n");_Exit(1);}}free(jobs);free(threads);e->launched+=started;if(started)e->parallel_frontiers++;if(started)fprintf(stderr,"DOC11_MANAGED_PARALLEL: lanes=%zu workers=%zu\n",tasks,started+1);for(size_t k=0;k<tasks;k++){Cell *c=e->cell+queue[k];if(c->failed){fprintf(stderr,"DOC: %s\n",c->error?c->error:"candidate failure");return 0;}}return 1;}
typedef struct {Epoch *e;const size_t *queue;size_t count;int ok;} CpuFrontier;
static void *cpu_frontier(void *opaque){CpuFrontier *f=opaque;f->ok=execute_cpu(f->e,f->queue,f->count);return NULL;}
static int execute_frontier(Epoch *e,size_t tasks){if(epoch_cancelled(e))return 0;
#ifdef DOC_ENABLE_PLACED
if(e->placed){if(!placed_execute(e,tasks)||epoch_cancelled(e))return 0;e->frontiers++;e->evaluations+=tasks;for(size_t k=0;k<tasks;k++)publish_private(e,e->queue[k]);return 1;}
#endif
int ok=1;size_t *cpu=NULL,*gpu=NULL,nc=0,ng=0;pthread_t thread;int started=0;CpuFrontier f={0};if(gpu_mode){if(!gpu_healthy())return 0;cpu=zalloc(tasks,sizeof(*cpu));gpu=zalloc(tasks,sizeof(*gpu));if(!cpu||!gpu){free(cpu);free(gpu);return 0;}for(size_t k=0;k<tasks;k++){size_t id=e->queue[k];if(gpu_eligible(e,id))gpu[ng++]=id;else cpu[nc++]=id;}int route=(int)num(F_place_device(vi(gpu_mode),vi((int64_t)ng),vi((int64_t)nc)));if(route<0){fprintf(stderr,"DOC_GPU_UNSUPPORTED: explicit GPU frontier has unsupported lanes\n");ok=0;}else if(!route){ok=execute_cpu(e,e->queue,tasks);nc=tasks;ng=0;}else {f=(CpuFrontier){e,cpu,nc,1};if(nc&&ng&&!pthread_create(&thread,NULL,cpu_frontier,&f))started=1;else if(nc)f.ok=execute_cpu(e,cpu,nc);int g=gpu_execute(e,gpu,ng);if(started&&pthread_join(thread,NULL))_Exit(1);ok=f.ok&&g;}}else{nc=tasks;ok=execute_cpu(e,e->queue,tasks);}free(cpu);free(gpu);if(!ok||epoch_cancelled(e)||(gpu_mode&&!gpu_healthy()))return 0;e->frontiers++;e->evaluations+=tasks;if(ng)fprintf(stderr,"DOC11_GPU_FRONTIER: cpu=%zu gpu=%zu concurrent=%d\n",nc,ng,started);for(size_t k=0;k<tasks;k++)publish_private(e,e->queue[k]);return 1;}
static size_t find_state(const Epoch *e,const char *name,size_t len){for(size_t i=0;i<e->n;i++)if(e->states[i].name&&strlen(e->states[i].name)==len&&!memcmp(e->states[i].name,name,len))return i;return e->n;}
static int batch_private(Epoch *e,int argc,char **argv,size_t *target){if(epoch_cancelled(e))return 0;*target=e->n;int has_target=0;for(size_t i=0;i<e->n;i++)if(e->states[i].role==5&&!e->have[i]){if(!evaluate(e,i,NULL))return 0;publish_private(e,i);}for(int a=0;a<argc;a++){const char *arg=argv[a];if(!strncmp(arg,"--demand=",9)){if(has_target)return 0;has_target=1;*target=find_state(e,arg+9,strlen(arg+9));if(*target==e->n)return 0;continue;}if(!strcmp(arg,"--backend=cpu"))continue;if(!strncmp(arg,"--backend=",10))return 0;const char *eq=strchr(arg,'=');if(!eq)return 0;size_t i=find_state(e,arg,(size_t)(eq-arg));if(i==e->n||!source_role(e->states[i].role)||e->cell[i].supplied)return 0;e->cell[i].supplied=1;if(!evaluate(e,i,eq+1)){fprintf(stderr,"DOC: %s\n",e->cell[i].error);return 0;}publish_private(e,i);}for(size_t i=0;i<e->n;i++)if(e->states[i].role==1&&!e->have[i]){if(!evaluate(e,i,NULL))return 0;publish_private(e,i);}memset(e->need,*target==e->n?1:0,e->n);if(*target!=e->n){e->need[*target]=1;doc_demand(e->need);}for(;;){memset(e->blocked,0,e->n);doc_block(e->dirty,e->blocked);size_t tasks=doc_select(e->dirty,e->need,e->blocked,e->queue);if(!tasks)break;if(!execute_frontier(e,tasks))return 0;}for(size_t i=0;i<e->n;i++)if(e->states[i].name&&e->need[i]&&(!e->have[i]||e->dirty[i]))return 0;return !epoch_cancelled(e)&&(!gpu_mode||gpu_healthy());}
/* A single writer may prepare exactly one batch per open attempt. A failed or
 * repeated batch poisons that attempt; a caller's success flag cannot
 * publish a partial valuation. Only a successful stabilization sets ready. */
static int batch(Epoch *e,int argc,char **argv,size_t *target){if(!e->in_flight)return 0;if(e->batch_state){e->batch_state=1;return 0;}e->batch_state=1;
#ifdef DOC_ENABLE_PLACED
if(e->placed&&!placed_prepare_epoch(e,argc,argv))return 0;
#endif
if(!batch_private(e,argc,argv,target))return 0;e->batch_state=2;return 1;}
static void doc_process_metrics(void){if(!getenv("DOC_REGION_METRICS"))return;struct rusage usage;if(!getrusage(RUSAGE_SELF,&usage))fprintf(stderr,"DOC11_PROCESS_METRICS: max_rss_kib=%ld\n",usage.ru_maxrss);}
static void observe(const Epoch *e,size_t target,int epochs,size_t epoch){if(epochs)printf("epoch: %zu\n",epoch);for(size_t i=0;i<e->n;i++)if(e->states[i].name&&(target==e->n||target==i)){printf("%s: ",e->states[i].name);print(*e->states[i].slot);putchar('\n');}fflush(stdout);}
