static int run_reactive(const State *states,size_t n,int argc,char **argv){Epoch e;epoch_init(&e,states,n);int start=1;if(argc>1&&!strncmp(argv[1],"--asset-root=",13)){asset_root=argv[1]+13;start++;}if(start<argc&&!strncmp(argv[start],"--output-root=",14)){doc_output_root=argv[start++]+14;if(!*doc_output_root){epoch_free(&e);return 1;}}if(start<argc&&!strcmp(argv[start],"--backend=cpu"))start++;else if(start<argc&&(!strcmp(argv[start],"--backend=gpu")||!strcmp(argv[start],"--backend=auto"))){gpu_mode=!strcmp(argv[start++],"--backend=gpu")?1:2;if(!gpu_open(n)){gpu_close();if(gpu_mode==1||getenv("DOC_REQUIRE_PHYSICAL_GPU")){epoch_free(&e);fprintf(stderr,"DOC_GPU_UNAVAILABLE\n");return 1;}gpu_mode=0;}}if(start<argc&&(!strncmp(argv[start],"--through=",10)||!strncmp(argv[start],"--until=",8))){int ok=run_recurrence(&e,argc-start,argv+start);epoch_free(&e);gpu_close();if(live_bytes)fail("recurrence region leak");if(getenv("DOC_REGION_METRICS"))fprintf(stderr,"DOC11_REGIONS: live=%zu peak=%zu allocations=%zu\n",(size_t)live_bytes,(size_t)peak_bytes,(size_t)allocs);doc_process_metrics();return ok?0:1;}int multi=0;for(int i=start;i<argc;i++)if(!strcmp(argv[i],"--next"))multi=1;int success=1;size_t epoch=0;for(int i=start;i<=argc;i++)if(i==argc||!strcmp(argv[i],"--next")){if(!epoch_begin(&e)){success=0;break;}size_t target;success=batch(&e,i-start,argv+start,&target);success=epoch_finish(&e,success);if(!success){fprintf(stderr,"DOC: epoch rejected; previous publication retained\n");break;}observe(&e,target,multi,epoch++);fprintf(stderr,"DOC11_MANAGED_EVALUATIONS: %zu frontiers=%zu parallel=%zu launched=%zu\n",e.evaluations,e.frontiers,e.parallel_frontiers,e.launched);start=i+1;}epoch_free(&e);gpu_close();if(live_bytes)fail("epoch region leak");if(getenv("DOC_REGION_METRICS"))fprintf(stderr,"DOC11_REGIONS: live=%zu peak=%zu allocations=%zu\n",(size_t)live_bytes,(size_t)peak_bytes,(size_t)allocs);doc_process_metrics();return success?0:1;}
